function livingHash(v){return typeof missionHash==='function'?missionHash(String(v)):String(v).split('').reduce((h,c)=>Math.imul(h^c.charCodeAt(0),16777619)>>>0,2166136261)}
function livingPair(a,b){return [a,b].sort().join('::')}
function livingName(seed,i){let first=['Adrian','Alaric','Bastian','Corvin','Darian','Emeric','Leomar','Lucan','Orren','Tavian','Adelina','Celeste','Elara','Ilyra','Maelis','Rosamund','Sabine','Thalia','Vianne','Ysabel'],last=['Arquen','Bellafort','Corbray','Dorell','Eirenwald','Falcrest','Maroven','Rhenmark','Solvair','Veymont','Westerling','Zoric'];return `${first[livingHash(seed+':f:'+i)%first.length]} von ${last[livingHash(seed+':l:'+i)%last.length]}`}
function livingMakePerson(id,name,role,age,group,seed){let keys=Object.keys(LIVING_TRAITS),a=keys[livingHash(seed+':a:'+id)%keys.length],b=keys[livingHash(seed+':b:'+id)%keys.length];if(a===b)b=keys[(keys.indexOf(a)+3)%keys.length];return {id,name,role,age,group,alive:true,health:58+livingHash(seed+':hp:'+id)%36,relation:40+livingHash(seed+':rel:'+id)%31,trust:36+livingHash(seed+':trust:'+id)%36,influence:25+livingHash(seed+':inf:'+id)%55,traits:[a,b],traitScores:Object.fromEntries(keys.map(k=>[k,0])),memories:[],born:1487-age,death:null,heir:null}}
function livingInitialPeople(seed){let base=[['mother','Königinmutter','Königinmutter',39,'family'],['regent','Lady Mara Veyne','Kanzlerin',46,'council'],['marshal','Orric Falk','Marschall',51,'council'],['treasurer','Seraphine d’Aurel','Schatzmeisterin',42,'council'],['admiral','Corven Thale','Admiral',49,'council'],['confessor',livingName(seed,7),'Hofgeistlicher',55,'faith'],['physician',livingName(seed,8),'Leibärztin',37,'court'],['chamberlain',livingName(seed,9),'Kammerherr',44,'court']];return base.map(x=>livingMakePerson(...x,seed))}
function createLivingWorldState(seed){return {version:1,people:livingInitialPeople(seed),relations:{},foreign:{},treaties:[],drafts:{},civilWar:null,civilHistory:[],capital:{location:'throne',usedTurn:0,history:[],districtTrust:Object.fromEntries(Object.keys(LIVING_CAPITAL).map(k=>[k,45]))},journey:null,journeyHistory:[],traditions:{adopted:{},reputation:20,lastAdoptedYear:1482,history:[]},production:{chains:Object.fromEntries(Object.keys(LIVING_CHAINS).map(k=>[k,{level:1,priority:false,stock:6,efficiency:60,usedTurn:0,history:[]}]))},age:{id:'recovery',entered:1487,history:[]},annualYear:1487,news:[]}}
function migrateLivingWorld(old,seed){let f=createLivingWorldState(seed),l=old&&typeof old==='object'?old:{};l={...f,...l};l.people=Array.isArray(l.people)&&l.people.length?l.people.map((p,i)=>({...livingMakePerson(p.id||'person_'+i,p.name||livingName(seed,i),p.role||'Höfling',p.age||30,p.group||'court',seed),...p,traits:Array.isArray(p.traits)?p.traits:[],traitScores:{...Object.fromEntries(Object.keys(LIVING_TRAITS).map(k=>[k,0])),...(p.traitScores||{})},memories:Array.isArray(p.memories)?p.memories:[]})):f.people;l.relations=l.relations&&typeof l.relations==='object'?l.relations:{};l.foreign=l.foreign&&typeof l.foreign==='object'?l.foreign:{};l.treaties=Array.isArray(l.treaties)?l.treaties:[];l.drafts=l.drafts&&typeof l.drafts==='object'?l.drafts:{};l.civilHistory=Array.isArray(l.civilHistory)?l.civilHistory:[];l.capital={...f.capital,...(l.capital||{}),districtTrust:{...f.capital.districtTrust,...(l.capital?.districtTrust||{})},history:Array.isArray(l.capital?.history)?l.capital.history:[]};l.journeyHistory=Array.isArray(l.journeyHistory)?l.journeyHistory:[];l.traditions={...f.traditions,...(l.traditions||{}),adopted:{...(l.traditions?.adopted||{})},history:Array.isArray(l.traditions?.history)?l.traditions.history:[]};l.production={...f.production,...(l.production||{}),chains:{...f.production.chains,...(l.production?.chains||{})}};for(const id in f.production.chains)l.production.chains[id]={...f.production.chains[id],...(l.production.chains[id]||{}),history:Array.isArray(l.production.chains[id]?.history)?l.production.chains[id].history:[]};l.age={...f.age,...(l.age||{}),history:Array.isArray(l.age?.history)?l.age.history:[]};l.news=Array.isArray(l.news)?l.news:[];return l}
function ensureLiving(){if(!state.living?.people)state.living=migrateLivingWorld(state.living,state.nameSeed);livingSyncCast();return state.living}
function livingNews(title,text,kind='world'){let l=ensureLiving();l.news.unshift({turn:state.turn,year:state.year,title,text,kind});l.news=l.news.slice(0,60)}
function livingPerson(id){return ensureLiving().people.find(p=>p.id===id&&p.alive)}
function livingRelation(a,b){let l=ensureLiving(),key=livingPair(a,b);return l.relations[key]||(l.relations[key]={affinity:45+livingHash(state.nameSeed+key)%21,trust:40+livingHash(key+state.nameSeed)%26,attraction:0,rivalry:5,memories:[]})}
function livingAddMemory(personId,title,text,valence,importance=2){let p=livingPerson(personId);if(!p)return;let m={turn:state.turn,year:state.year,title,text,valence:clamp(valence,-10,10),importance:clamp(importance,1,5)};p.memories.unshift(m);p.memories=p.memories.slice(0,18);p.relation+=valence*importance*.42;p.trust+=valence>0?importance*.5:-importance*.7;if(valence<0)p.traitScores.bitter+=importance;else{p.traitScores.loyal+=importance*.6;p.traitScores.compassionate+=/gnade|hilfe|famil|kind/i.test(title+' '+text)?importance:0}livingEvolvePerson(p)}
function livingEvolvePerson(p){for(const [id,score] of Object.entries(p.traitScores)){if(score<12||p.traits.includes(id))continue;p.traits.push(id);if(p.traits.length>3)p.traits.shift();livingNews(`${p.name} verändert sich`,`${p.name} gilt am Hof zunehmend als ${LIVING_TRAITS[id][0].toLowerCase()}. Erlebnisse und Erinnerungen haben den Charakter sichtbar geformt.`,'person')}}
function livingSyncCast(){let l=state.living;if(!l)return;let names=typeof ensureCastNames==='function'?ensureCastNames():null,m=l.people.find(p=>p.id==='mother');if(m&&names?.mother)m.name=names.mother;let spouse=l.people.find(p=>p.id==='spouse');if(state.life?.spouse&&!spouse)l.people.push(livingMakePerson('spouse',state.life.spouse,'Königliche Gemahlin',Math.max(18,state.life.age-1),'family',state.nameSeed));for(let i=0;i<(state.life?.children||[]).length;i++){let c=state.life.children[i],id='child_'+i,p=l.people.find(x=>x.id===id);if(!p)l.people.push(livingMakePerson(id,c.name,'Königliches Kind',c.age,'family',state.nameSeed+i));else{p.name=c.name;p.age=c.age}}let g=state.grand;if(g?.houses)for(const h of g.houses){let id='noble_'+h.id,p=l.people.find(x=>x.id===id);if(!p)l.people.push(livingMakePerson(id,h.head,`Oberhaupt von ${h.name}`,35+livingHash(h.id+state.nameSeed)%26,'nobility',state.nameSeed));else p.name=h.head}}
function livingRememberDecision(title,text,meta={}){if(!state.living)return;let l=ensureLiving(),kind=meta.kind||'realm',targets=kind==='private'?l.people.filter(p=>p.group==='family'):kind==='war'?l.people.filter(p=>p.id==='marshal'||p.group==='nobility'):kind==='economy'?l.people.filter(p=>p.id==='treasurer'||p.group==='court'):kind==='diplomacy'?l.people.filter(p=>p.id==='regent'||p.group==='nobility'):l.people.filter(p=>p.group==='council'||p.group==='nobility').slice(0,5),words=(title+' '+text).toLowerCase(),positive=/hilfe|gnade|ausgleich|famil|fördern|schützen|frieden|freiheit|versorg/.test(words),negative=/hinricht|zwingen|enteign|demütig|verrat|vernicht|ausbeut/.test(words),val=positive?2:negative?-3:0;for(const p of targets){let personal=val;if(p.traits.includes('martial')&&kind==='war')personal+=2;if(p.traits.includes('mercantile')&&kind==='economy')personal+=2;if(p.traits.includes('devout')&&/glaube|tempel|kirche/.test(words))personal+=2;if(p.traits.includes('compassionate')&&negative)personal-=2;livingAddMemory(p.id,title,text,personal,Math.min(5,2+Math.abs(personal)))}livingTraditionEcho(words,kind)}

function livingForeignRealm(name){let l=ensureLiving(),f=l.foreign[name];if(f)return f;let ruler=typeof foreignRulerName==='function'?foreignRulerName(name,COUNTRY_META[countryRegionId(name)]?.ruler||name):name;f=l.foreign[name]={ruler,age:31+livingHash(name+state.nameSeed)%28,health:55+livingHash('hp'+name+state.nameSeed)%36,temper:['vorsichtig','ehrgeizig','kriegerisch','geschäftssinnig','fromm'][livingHash(name)%5],heir:livingName(state.nameSeed,name.length),heirAge:8+livingHash('heir'+name)%24,generation:1,memories:[],successionRisk:10+livingHash('risk'+name)%35};return f}
function livingGenerationTick(){let l=ensureLiving();for(const p of l.people.filter(p=>p.alive)){if(!p.id.startsWith('child_'))p.age++;p.health-=p.age>65?2:p.age>50?.5:0;let risk=p.age<48?0:p.age<60?2:p.age<72?5:11;if(p.health<28)risk+=8;if(livingHash(`${state.nameSeed}:death:${state.year}:${p.id}`)%100<risk){p.alive=false;p.death=state.year;livingNews(`${p.name} ist gestorben`,`${p.role} ${p.name} stirbt im Alter von ${p.age}. Ämter, Freundschaften, Feindschaften und unerledigte Versprechen bleiben zurück.`,'generation');livingReplacePerson(p)}}for(const name of Object.keys(state.relations||{})){let f=livingForeignRealm(name);f.age++;f.heirAge++;f.health-=f.age>65?2:0;let risk=f.age<55?1:f.age<70?5:12;if(f.health<30)risk+=10;if(livingHash(`${state.nameSeed}:foreign-death:${state.year}:${name}`)%100<risk){let old=f.ruler;f.ruler=f.heir;f.age=f.heirAge;f.health=64+livingHash(old+state.year)%25;f.heir=livingName(state.nameSeed+state.year,name.length+f.generation);f.heirAge=6+livingHash('next'+name+state.year)%20;f.generation++;let inherited=Math.round((state.relations[name]||0)*.45),temperShift=f.temper==='kriegerisch'?-8:f.temper==='geschäftssinnig'?4:0;state.relations[name]=clamp(inherited+temperShift,-100,100);livingNews(`Thronwechsel in ${name}`,`${old} ist tot. ${f.ruler} übernimmt Krone, Schulden und die Geschichten über Valdoria – doch nicht dieselben Gefühle. Die Beziehung beginnt bei ${state.relations[name]}.`,'generation')}}}
function livingReplacePerson(old){let l=ensureLiving(),idx=l.people.length,n=livingMakePerson('person_'+state.year+'_'+idx,livingName(state.nameSeed+state.year,idx),old.role,22+livingHash(old.id+state.year)%19,old.group,state.nameSeed+state.year);n.relation=clamp(45+Math.round(old.relation*.2),20,75);n.memories=old.memories.slice(0,3).map(m=>({...m,title:`Überliefert: ${m.title}`,importance:Math.max(1,m.importance-1)}));l.people.push(n);if(old.group==='nobility'){let hid=old.id.replace('noble_',''),h=state.grand?.houses?.find(h=>h.id===hid);if(h){h.head=n.name;h.generation=(h.generation||1)+1}}}

function livingTreatyDraft(name,peace=false){let l=ensureLiving(),key=(peace?'peace:':'treaty:')+name,d=l.drafts[key];if(!d)d=l.drafts[key]={country:name,peace,clauses:peace?['prisoners','nonaggression']:['trade'],duration:10,lastChanged:state.turn};return d}
function livingTreatyScore(name,draft){let rel=state.relations[name]||0,w=typeof warSnapshot==='function'?warSnapshot(name):null,world=state.depth?.world?.[name],demand=draft.clauses.reduce((s,id)=>s+(LIVING_TREATY_CLAUSES[id]?.cost||0),0),offer=(draft.clauses.includes('trade')?4:0)+(draft.clauses.includes('marriage')?5:0)+(draft.clauses.includes('prisoners')?8:0),leverage=draft.peace?(w?.progress||0)*.42+(w?.c?.exhaustion||0)*.2:0;return Math.round(50+rel*.42+offer+leverage-demand+(world?.posture==='offen feindselig'?-12:0))}
function livingTreatyPanel(id){let m=COUNTRY_META[id];if(!m||isAnnexed(id))return '';let name=m.key,war=!!state.diplo?.[name]?.war,d=livingTreatyDraft(name,war),score=clamp(livingTreatyScore(name,d),0,100),allowed=Object.entries(LIVING_TREATY_CLAUSES).filter(([,c])=>!war||c.peace).map(([cid,c])=>`<button data-living-treaty="${name}:${war?'peace':'treaty'}:toggle:${cid}" class="${d.clauses.includes(cid)?'active':''}"><b>${c.name}</b><span>${c.text}</span><em>${c.cost<0?'ENTGEGENKOMMEN':'FORDERUNG '+c.cost}</em></button>`).join('');return `<section class="living-treaty"><div class="living-treaty-head"><div><small>${war?'FRIEDENSKONGRESS':'VERTRAGSWERKSTATT'} · ${name}</small><h3>${war?'Den Krieg durch einen wirklichen Vertrag beenden':'Klauseln statt einer einzelnen Bündnis-Schaltfläche'}</h3><p>Jede Klausel bleibt über Jahre wirksam, kann verletzt werden und wird von beiden Höfen erinnert.</p></div><div class="acceptance-dial" style="--accept:${score}"><b>${score}%</b><span>ZUSTIMMUNG</span></div></div><div class="treaty-clauses">${allowed}</div><div class="treaty-footer"><span>${d.clauses.length} Klauseln · ${d.duration} Jahre</span><button data-living-treaty="${name}:${war?'peace':'treaty'}:submit:send">${war?'FRIEDENSANGEBOT ÜBERMITTELN':'VERTRAG ZUR RATIFIKATION SENDEN'}</button></div></section>`}
function livingTreatyAction(code){let [name,mode,act,id]=code.split(':'),peace=mode==='peace',d=livingTreatyDraft(name,peace);if(act==='toggle'){if(!LIVING_TREATY_CLAUSES[id]||(!LIVING_TREATY_CLAUSES[id].peace&&peace))return false;d.clauses=d.clauses.includes(id)?d.clauses.filter(x=>x!==id):[...d.clauses,id];d.lastChanged=state.turn;persist();render(false);return true}if(act!=='submit'||!d.clauses.length)return false;let score=livingTreatyScore(name,d),roll=livingHash(`${state.nameSeed}:treaty:${name}:${state.turn}:${d.clauses.join()}`)%100,accepted=roll<score;if(!accepted){state.relations[name]-=4;let text=`Der Hof von ${name} lehnt das Paket ab. Einzelne Klauseln erschienen tragfähig, doch Forderungen und Vertrauen ergaben noch keinen unterschriftsreifen Ausgleich.`;livingNews(`Vertrag mit ${name} gescheitert`,text,'treaty');recordDecision(`${peace?'Friedensangebot':'Vertragsangebot'} an ${name}`,text,{kind:'diplomacy',target:name});persist();render();toast('Der andere Hof lehnt ab',`${score}% erwartete Zustimmung reichten diesmal nicht.`);return true}livingRatifyTreaty(name,d);return true}
function livingRatifyTreaty(name,d){let l=ensureLiving(),clauses=[...d.clauses],t={id:`treaty_${state.turn}_${livingHash(name)%999}`,country:name,clauses,signedYear:state.year,expiresYear:state.year+d.duration,status:'active',trust:55,violations:[],peace:d.peace};l.treaties.push(t);let dip=state.diplo[name]||(state.diplo[name]={});if(d.peace){dip.war=false;dip.treaty='peace';let id=countryRegionId(name);if(clauses.includes('territory')&&territoryPolicy(id).occupied)annexTerritory(id,'ausgehandeltem Friedensvertrag',false);if(clauses.includes('vassal')){let p=state.countryPolicy[name]||(state.countryPolicy[name]={});p.vassal=true;state.relations[name]=Math.max(15,state.relations[name])}if(clauses.includes('reparations'))t.reparationsLeft=5;if(clauses.includes('disarm')&&id)state.regions[id].garrison=Math.max(12,state.regions[id].garrison-12)}else dip.treaty=clauses.includes('defense')?'alliance':clauses.includes('trade')?'trade':'pact';if(clauses.includes('marriage'))state.diploMarried[name]=true;if(clauses.includes('trade'))state.stats.trade+=2;if(clauses.includes('knowledge'))state.stats.intelligence+=2;state.relations[name]+=8;delete l.drafts[(d.peace?'peace:':'treaty:')+name];let text=`${name} und Valdoria ratifizieren ${clauses.map(c=>LIVING_TREATY_CLAUSES[c].name).join(', ')}. Der Vertrag gilt bis ${t.expiresYear}; Verletzungen verändern Vertrauen und spätere Verhandlungen.`;livingNews(`Vertrag mit ${name} ratifiziert`,text,'treaty');recordDecision(`Vertrag von ${name}`,text,{kind:'diplomacy',target:name});normalizeState();persist();render();toast('Siegel beider Reiche',`${clauses.length} Klauseln treten in Kraft.`)}
function livingTreatyTick(){let l=ensureLiving();for(const t of l.treaties.filter(t=>t.status==='active')){let dip=state.diplo[t.country]||{};if(state.year>=t.expiresYear){t.status='expired';livingNews(`Vertrag mit ${t.country} ausgelaufen`,'Die Klauseln verlieren ihre bindende Kraft. Beide Höfe müssen entscheiden, ob Gewohnheit, Erneuerung oder neue Rivalität folgt.','treaty');continue}if(t.reparationsLeft>0){let w=state.depth?.world?.[t.country],pay=Math.min(700000,Math.max(100000,(w?.treasury||20)*10000));state.reserve+=pay;if(w)w.treasury-=pay/1000000;t.reparationsLeft--}if(t.clauses.includes('trade')&&!dip.war){state.stats.trade+=.18;t.trust+=.15}if(t.clauses.includes('knowledge'))state.stats.intelligence+=.1;if(t.clauses.includes('nonaggression')&&dip.war){t.violations.push({year:state.year,by:'unknown'});t.status='broken';state.stats.legitimacy-=4;t.trust-=30;livingNews(`Vertrag mit ${t.country} gebrochen`,'Der Krieg verletzt den verbrieften Nichtangriffspakt. Andere Höfe zweifeln nun an valdorischen Siegeln.','treaty')}}}

function livingCivilRisk(){let l=ensureLiving(),houses=state.grand?.houses||[],danger=houses.reduce((s,h)=>s+Math.max(0,35-h.relation)+Math.max(0,h.claim-45),0)/Math.max(1,houses.length),prov=Object.values(state.regions).reduce((s,r)=>s+Math.max(0,r.unrest-45),0)/8;return clamp(Math.round((100-state.stats.stability)*.35+(100-state.stats.legitimacy)*.25+danger*.55+prov),0,100)}
function livingStartCivilWar(forced=false){let l=ensureLiving();if(l.civilWar||state.life.age<16)return false;let risk=livingCivilRisk();if(!forced&&(risk<64||livingHash(`${state.nameSeed}:civil:${state.year}`)%100>risk-32))return false;let houses=[...(state.grand?.houses||[])].sort((a,b)=>(b.claim+b.power-b.relation)-(a.claim+a.power-a.relation)),leader=houses[0],eligible=Object.keys(state.regions).filter(id=>grandOwnsRegion(id)&&id!=='falkenkrone'),provinces=eligible.filter(id=>livingHash(id+leader?.id+state.year)%100<38).slice(0,3);if(!provinces.length)provinces=[eligible[0]||'caerhaven'];l.civilWar={leaderId:leader?.id,leader:leader?.head||'ein entfernter Prinz',house:leader?.name||'eine Adelsliga',claimant:livingName(state.nameSeed+state.year,41),provinces,support:35+risk/3,royal:55+state.stats.legitimacy/3,progress:50,phase:'LAGER BILDEN SICH',startedYear:state.year,usedTurn:0,history:[]};for(const id of provinces)state.regions[id].unrest+=18;state.stats.stability-=10;let text=`${l.civilWar.house} ruft ${l.civilWar.claimant} als Gegenkönig aus. ${provinces.map(id=>state.regions[id].name).join(', ')} verweigern vorerst Steuern und Befehle. Verhandlung, Zugeständnisse und Feldzüge werden den Ausgang gemeinsam bestimmen.`;livingNews('Ein Gegenkönig wird ausgerufen',text,'civil');state.events.unshift({turn:state.turn,date:dateLabel(),title:'Der Krieg der zwei Kronen',text});return true}
function livingCivilPanel(){let l=ensureLiving(),c=l.civilWar;if(!c){let risk=livingCivilRisk();return panel('INNERER FRIEDEN',`${risk}% dynastisches Krisenrisiko`,`<div class="civil-peace"><div><small>WARNSIGNALE</small><b>${risk<35?'Der Thron ist sicher':risk<60?'Häuser prüfen ihre Möglichkeiten':'Lagerbildung droht'}</b><p>Ansprüche, Hausmacht, Provinzunruhe, Legitimität und frühere Kränkungen wirken gemeinsam. Ein Bürgerkrieg entsteht nicht aus einem einzelnen Zufallswurf.</p></div><div class="civil-risk"><i style="width:${risk}%"></i></div></div>`,'span-12')}let used=c.usedTurn===state.turn;return `<section class="civil-war"><div class="civil-war-head"><div><small>BÜRGERKRIEG · SEIT ${c.startedYear}</small><h2>${c.claimant} gegen die Krone</h2><p>${c.house} führt ${c.provinces.map(id=>state.regions[id].name).join(', ')}. Phase: ${c.phase}.</p></div><div><b>${Math.round(c.progress)}%</b><span>KÖNIGLICHE LAGE</span></div></div><div class="civil-front"><i style="width:${c.progress}%"></i></div><div class="civil-actions">${[['parley','UNTERHÄNDLER SENDEN','Einzelne Beschwerden anerkennen und das gegnerische Lager spalten.'],['charter','BEGRENZTE ZUGESTÄNDNISSE','Rechte verbriefen; den Krieg politisch beenden, aber Kronmacht abgeben.'],['amnesty','AMNESTIE VERKÜNDEN','Niedere Gefolgsleute zur Heimkehr bewegen.'],['propaganda','DEN ANSPRUCH WIDERLEGEN','Archive, Predigten und Öffentlichkeit für die eigene Linie einsetzen.'],['mobilize','TREUE HEERE SAMMELN','Gold und Offiziersloyalität in militärische Überlegenheit umwandeln.'],['battle','ENTSCHEIDUNGSSCHLACHT SUCHEN','Hoher möglicher Fortschritt, Verluste und ein schwerer Rückschlag.']].map(x=>`<button data-civil-action="${x[0]}" ${used?'disabled':''}><b>${x[1]}</b><span>${x[2]}</span></button>`).join('')}</div>${c.history.length?`<div class="civil-history">${c.history.slice(0,4).map(h=>`<p><b>${h.year} · ${h.action}</b>${h.text}</p>`).join('')}</div>`:''}</section>`}
function livingCivilAction(act){let c=ensureLiving().civilWar;if(!c||c.usedTurn===state.turn)return false;let text='',delta=0;if(act==='parley'){if(state.reserve<600000)return toast('Gesandtschaft','0,6 Mio. Gold fehlen.');state.reserve-=600000;delta=7+Math.round(state.life.diplomacy/18);c.support-=6;text='Unterhändler trennen alte Beschwerden von der Frage des Throns. Einige Banner beginnen zu zweifeln.'}else if(act==='charter'){delta=18;c.support-=13;state.life.authority-=7;ensureGrand().government.mandate-=6;text='Die Krone bestätigt regionale und adlige Rechte. Ein Teil der Rebellion verliert seinen Grund, doch die Verfassung verändert sich dauerhaft.'}else if(act==='amnesty'){delta=10;c.support-=10;state.stats.legitimacy+=2;text='Niedere Gefolgsleute dürfen ohne Enteignung heimkehren. Hardliner bleiben, aber das Heer des Gegenkönigs schrumpft.'}else if(act==='propaganda'){if(ensureDepth().economy.goods.knowledge.stock<5)return toast('Archive und Drucker','Für eine glaubwürdige Kampagne fehlt Wissen in den Speichern.');ensureDepth().economy.goods.knowledge.stock-=5;delta=5+Math.round(state.stats.intelligence/17);state.factions.people-=1;text='Stammbäume, Predigten und Berichte widerlegen den Gegenanspruch – soweit Menschen der königlichen Fassung vertrauen.'}else if(act==='mobilize'){if(state.militaryFund<2500000)return toast('Militärfonds','2,5 Mio. Gold fehlen.');state.militaryFund-=2500000;delta=10+Math.round(state.stats.army/20);c.royal+=8;state.factions.officers+=2;text='Treue Regimenter, Magazine und Brücken werden unter ein Kommando gestellt. Die Krone gewinnt militärische Handlungsfreiheit.'}else if(act==='battle'){let odds=clamp(42+(c.royal-c.support)*.45+state.armies[0].morale/8,18,88),win=livingHash(`${state.nameSeed}:civil-battle:${state.turn}`)%100<odds,loss=win?700:1700;state.armies[0].strength=Math.max(2000,state.armies[0].strength-loss);delta=win?24:-17;c.support+=win?-12:10;text=win?`Das königliche Heer behauptet das Feld. ${loss} Mann fallen oder werden verwundet; mehrere Banner wechseln die Seite.`:`Die Schlacht endet im Rückzug. ${loss} Mann gehen verloren, und der Gegenkönig gewinnt neue Anhänger.`}else return false;c.progress=clamp(c.progress+delta,0,100);c.usedTurn=state.turn;c.history.unshift({year:state.year,turn:state.turn,action:act,text});recordDecision(`Bürgerkrieg · ${act}`,text,{kind:'war'});if(c.progress>=100)livingEndCivilWar(true);else if(c.progress<=0)livingEndCivilWar(false);normalizeState();persist();render();return true}
function livingCivilTick(){let l=ensureLiving(),c=l.civilWar;if(!c){livingStartCivilWar(false);return}let rebel=3+c.support/30,royal=2+c.royal/34+(state.stats.stability-50)/30;c.progress+=royal-rebel;for(const id of c.provinces)state.regions[id].unrest+=c.progress<45?2:-.5;if(c.progress>=100)livingEndCivilWar(true);else if(c.progress<=0)livingEndCivilWar(false)}
function livingEndCivilWar(win){let l=ensureLiving(),c=l.civilWar;if(!c)return;if(win){state.stats.legitimacy+=8;state.stats.stability+=5;let h=state.grand?.houses?.find(h=>h.id===c.leaderId);if(h){h.power-=12;h.claim-=20;h.relation-=10}for(const id of c.provinces)state.regions[id].unrest-=12}else{state.stats.legitimacy-=15;state.stats.stability-=10;state.life.authority-=12}let text=win?`${c.claimant} verzichtet auf die Krone oder flieht. Das Reich ist wieder vereint, aber Gräber, neue Rechte und persönliche Erinnerungen bleiben.`:`Die königliche Sache bricht zusammen. Ein erzwungener Ausgleich beschneidet die Krone und macht ${c.house} zum Mitträger der Herrschaft.`;l.civilHistory.unshift({...c,endedYear:state.year,win});l.civilWar=null;livingNews(win?'Die zwei Kronen werden wieder eine':'Der Gegenkönig erzwingt einen Vergleich',text,'civil');state.events.unshift({turn:state.turn,date:dateLabel(),title:'Ende des Bürgerkriegs',text})}
function livingCivilMapLayer(){let c=ensureLiving().civilWar;if(!c)return '';return `<g class="civil-map-layer">${c.provinces.map(id=>`<path d="${REGION_RENDER_SHAPES[id]}"/><text x="${MAP_POINTS[id].x}" y="${MAP_POINTS[id].y+70}">GEGENKRONE</text>`).join('')}</g>`}

function livingCapitalPanel(){let l=ensureLiving(),c=l.capital,current=LIVING_CAPITAL[c.location],districts=Object.entries(LIVING_CAPITAL).map(([id,d])=>`<button data-capital-action="move:${id}" class="${c.location===id?'active':''}" ${c.location===id?'disabled':''}><i>${d.icon}</i><b>${d.name}</b><span>${d.text}</span><em>VERTRAUEN ${Math.round(c.districtTrust[id])}</em></button>`).join(''),actions=current.actions.map(a=>`<button data-capital-action="act:${a[0]}" ${c.usedTurn===state.turn||state.private.actionPoints<1?'disabled':''}><b>${a[1]}</b><span>${a[2]}</span></button>`).join('');return panel('FALKENKRONE BEGEHEN',`${current.icon} ${current.name} · eine Hauptstadt mit eigenen Menschen`,`<div class="capital-map"><svg viewBox="0 0 700 360"><path class="capital-wall" d="M110 300 Q55 210 105 95 Q210 25 365 45 Q560 25 625 140 Q665 260 570 320 Q335 355 110 300Z"/><path class="capital-river" d="M0 275 Q190 220 350 275 T700 250"/>${Object.entries(LIVING_CAPITAL).map(([id,d],i)=>{let x=125+(i%4)*150,y=105+Math.floor(i/4)*145;return `<g class="capital-node ${c.location===id?'active':''}" transform="translate(${x} ${y})"><circle r="24"/><text y="4">${d.icon}</text><text class="capital-label" y="42">${d.name}</text></g>`}).join('')}</svg><div class="capital-current"><small>HEUTE IN</small><h3>${current.name}</h3><p>${current.text}</p><div>${actions}</div></div></div><div class="capital-districts">${districts}</div>`,'span-12')}
function livingCapitalAction(code){let [act,id]=code.split(':'),l=ensureLiving(),c=l.capital;if(act==='move'){if(!LIVING_CAPITAL[id])return false;c.location=id;c.history.unshift({turn:state.turn,year:state.year,type:'move',id});persist();render(false);return true}if(act!=='act'||c.usedTurn===state.turn||state.private.actionPoints<1)return false;let current=LIVING_CAPITAL[c.location],action=current.actions.find(a=>a[0]===id);if(!action)return false;state.private.actionPoints--;c.usedTurn=state.turn;c.districtTrust[c.location]+=4;let text='';if(id==='audience'){state.factions.people+=3;state.stats.stability+=1;text='Bittsteller sprechen ohne vorab gefilterte Listen. Der König erkennt Probleme früher, verspricht aber mehr, als Beamte sofort erfüllen können.'}else if(id==='ceremony'){state.stats.legitimacy+=3;state.private.stress+=2;text='Ränge und Eide werden öffentlich bestätigt. Der Hof sieht Ordnung; jene ohne Platz sehen Abstand.'}else if(id==='supper'){state.private.stress-=6;for(const p of ensureLiving().people.filter(p=>p.group==='family'))livingAddMemory(p.id,'Abend im Familienflügel','Der König blieb beim gemeinsamen Tisch.',3,3);text='Ein Abend ohne Akten verändert kleine Gesten und alte Spannungen in der Familie.'}else if(id==='child'){let child=state.life.children[0];if(child){child.education+=3;let p=livingPerson('child_0');if(p){p.traitScores.compassionate+=2;p.traitScores.scholarly+=2}}text=child?`Zeit mit ${child.name} prägt Erziehung und Vertrauen.`:'Noch lebt kein eigenes Kind im Familienflügel.'}else if(id==='briefing'){ensureGrand().government.mandate+=3;state.stats.intelligence+=1;text='Fachleute widersprechen einander vor Karten und Berichten; der König entscheidet nach sichtbarer Abwägung.'}else if(id==='private_council'){let p=ensureLiving().people.filter(p=>p.group==='council').sort((a,b)=>a.relation-b.relation)[0];livingAddMemory(p.id,'Vertraulicher Rat','Der König hörte die leiseste Stimme im kleinen Kreis.',4,3);text=`${p.name} erhält ungewohnt direkten Zugang und wird dies politisch nutzen.`}else if(id==='research'){state.stats.intelligence+=2;ensureDepth().economy.goods.knowledge.stock+=3;text='Schreiber finden einen vergessenen Vertrag und ordnen ihn in die gegenwärtige Politik ein.'}else if(id==='record'){ensureLiving().traditions.reputation+=2;text='Die königliche Fassung eines umstrittenen Jahres wird versiegelt – nicht als Wahrheit, sondern als mächtige Erinnerung.'}else if(id==='service'){state.stats.legitimacy+=2;state.factions.people+=2;grandScoreTrait('devout',2);text='Die Krone teilt Ritual und Almosen sichtbar mit der Stadt.'}else if(id==='vigil'){state.private.stress-=9;state.life.empathy+=2;text='Die Nachtwache schafft Ruhe, aber auch Raum für Zweifel und Trauer.'}else if(id==='walk'){let p=ensureLiving().people.filter(p=>p.alive).sort((a,b)=>a.relation-b.relation)[0];livingAddMemory(p.id,'Spaziergang in den Terrassen','Der König suchte ein Gespräch ohne Zeugen.',5,3);text=`Ein offenes Gespräch mit ${p.name} verändert eine schwierige Beziehung.`}else if(id==='alone'){state.private.stress-=8;state.private.health+=2;text='Der König bleibt allein. Der Hof deutet Abwesenheit, der Mensch gewinnt Atem.'}else if(id==='inspect'){ensureDepth().economy.goods.timber.stock+=2;state.stats.navy+=1;text='Am Kai werden fehlende Taue, verspätete Lieferungen und gute Werkstätten sichtbar.'}else if(id==='incognito'){state.stats.intelligence+=2;state.private.secret+=4;state.factions.people+=2;text='In Tavernen hört der König, was im Thronsaal niemand sagt – und riskiert erkannt zu werden.'}else if(id==='workshop'){ensureDepth().innovation.knowledge+=4;ensureLiving().production.chains.arms.efficiency+=2;text='Meister und Lehrlinge zeigen Engpässe, kleine Erfindungen und den Preis königlicher Aufträge.'}else{state.factions.people+=4;ensureDepth().economy.goods.grain.stock-=2;text='Die Brotausgabe schafft unmittelbare Nähe und macht sichtbar, wie schnell Vorräte zu Politik werden.'}recordDecision(`${current.name} · ${action[1]}`,text,{kind:'private'});normalizeState();persist();render();return true}

function livingJourneyPanel(){let l=ensureLiving(),j=l.journey;if(j)return panel('KÖNIGSREISE',`${j.destinationName} · Etappe ${j.step+1} von ${j.total}`,`<div class="journey-active"><div><small>${j.route.toUpperCase()} · MIT ${j.companionName.toUpperCase()}</small><h2>${j.event.title}</h2><p>${j.event.text}</p></div><div class="journey-road"><i style="width:${(j.step+1)/j.total*100}%"></i></div><div class="journey-choices">${j.event.choices.map(c=>`<button data-journey-action="choice:${c.id}"><b>${c.label}</b><span>${c.text}</span></button>`).join('')}</div></div>`,'span-12');let dests=typeof travelDestinations==='function'?travelDestinations().filter(d=>d.id!=='falkenkrone').slice(0,8):[],companions=ensureLiving().people.filter(p=>p.alive&&(p.group==='family'||p.group==='council')).slice(0,8);return panel('KÖNIGSREISEN PLANEN','Route, Begleitung und mehrere Entscheidungen statt eines einzelnen Klicks',`<div class="journey-planner"><div><small>ZIEL</small>${dests.map(d=>`<button data-journey-setup="destination:${d.id}" class="${l.journeyDraft?.destination===d.id?'active':''}"><b>${d.name}</b><span>${d.kind==='own'?'Eigenes Land':'Fremder Hof'}</span></button>`).join('')}</div><div><small>REISEWEG</small>${[['road','KÖNIGSSTRASSE','Sichtbar und gut versorgt.'],['sea','ÜBER SEE','Schnell, wetterabhängig und maritim.'],['incognito','KLEINER ZUG','Offene Begegnungen, höheres Risiko.']].map(x=>`<button data-journey-setup="route:${x[0]}" class="${l.journeyDraft?.route===x[0]?'active':''}"><b>${x[1]}</b><span>${x[2]}</span></button>`).join('')}</div><div><small>BEGLEITUNG</small>${companions.map(p=>`<button data-journey-setup="companion:${p.id}" class="${l.journeyDraft?.companion===p.id?'active':''}"><b>${p.name}</b><span>${p.role}</span></button>`).join('')}</div></div><button class="journey-start" data-journey-action="start:journey" ${l.journeyDraft?.destination&&l.journeyDraft?.route&&l.journeyDraft?.companion&&state.private.actionPoints>0?'':'disabled'}>KÖNIGSREISE BEGINNEN<span>Eine Reise beansprucht einen privaten Aktionspunkt und entfaltet mehrere Etappen</span></button>`,'span-12')}
function livingJourneySetup(code){let [key,id]=code.split(':'),l=ensureLiving();l.journeyDraft=l.journeyDraft||{};if(!['destination','route','companion'].includes(key))return false;l.journeyDraft[key]=id;persist();render(false);return true}
function livingJourneyEvent(j){let pool=[{title:'Eine eingestürzte Brücke',text:'Fuhrwerke und Bittsteller stauen sich. Die Reise könnte warten, helfen oder einen Umweg nehmen.',choices:[['help','MITARBEITEN','Zeit verlieren, aber Menschen unmittelbar helfen.'],['engineers','PIONIERE VORAUSSCHICKEN','Gold und Fachleute für eine dauerhafte Reparatur einsetzen.'],['detour','DEN UMWEG NEHMEN','Die Reise schützen, ohne das örtliche Problem zu lösen.']]},{title:'Ein Dorf ohne Brot',text:'Der Ortsvorsteher zeigt leere Speicher, während Händler volle Wagen bewachen.',choices:[['stores','KRONVORRÄTE ÖFFNEN','Getreide verteilen und die Reiseversorgung belasten.'],['buy','DIE WAGEN AUFKAUFEN','Privates Gold einsetzen und Preise hochtreiben.'],['investigate','DIE KNAPPHEIT UNTERSUCHEN','Verantwortliche suchen, bevor Hilfe verteilt wird.']]},{title:'Ein Abend ohne Protokoll',text:'Am Feuer spricht die Begleitung über Dinge, die im Palast nie ausgesprochen würden.',choices:[['listen','NUR ZUHÖREN','Vertrauen schaffen, ohne sofort zu urteilen.'],['confess','EIGENE ZWEIFEL TEILEN','Große Nähe und politische Verwundbarkeit riskieren.'],['business','BEIM STAAT BLEIBEN','Die Gelegenheit für einen vertraulichen Lagebericht nutzen.']]},{title:'Reiter am Horizont',text:'Unbekannte Bewaffnete beobachten den Zug. Räuber, örtliche Eskorte oder ein politisches Signal?',choices:[['approach','ENTGEGENREITEN','Mut zeigen und die Absicht unmittelbar klären.'],['guard','WACHEN SCHLIESSEN LASSEN','Sicherheit vor Offenheit stellen.'],['hide','DIE KÖNIGLICHEN ZEICHEN VERBERGEN','Unauffällig weiterziehen und Gerüchte vermeiden.']]}];let idx=livingHash(`${state.nameSeed}:journey:${j.destination}:${j.step}:${state.turn}`)%pool.length,e=pool[idx];return {...e,choices:e.choices.map(x=>({id:x[0],label:x[1],text:x[2]}))}}
function livingJourneyAction(code){let [act,id]=code.split(':'),l=ensureLiving();if(act==='start'){let d=l.journeyDraft,p=d&&livingPerson(d.companion),dest=typeof travelDestinations==='function'?travelDestinations().find(x=>x.id===d?.destination):null;if(!d||!p||!dest||state.private.actionPoints<1)return false;state.private.actionPoints--;l.journey={destination:d.destination,destinationName:dest.name,route:d.route,companion:p.id,companionName:p.name,step:0,total:3+(d.route==='incognito'?1:0),startedTurn:state.turn,event:null,log:[]};l.journey.event=livingJourneyEvent(l.journey);l.journeyDraft=null;persist();render();return true}if(act!=='choice'||!l.journey)return false;let j=l.journey,p=livingPerson(j.companion),choice=j.event.choices.find(c=>c.id===id);if(!choice)return false;let val=0;if(id==='help'||id==='stores'){state.factions.people+=4;state.private.stress+=2;ensureDepth().economy.goods.grain.stock-=id==='stores'?5:0;val=4}else if(id==='engineers'){state.reserve=Math.max(0,state.reserve-600000);state.regions.caerhaven.infrastructure+=1;val=2}else if(id==='buy'){state.private.purse=Math.max(0,state.private.purse-180000);state.factions.people+=3;val=2}else if(id==='investigate'){state.stats.intelligence+=2;val=p.traits.includes('scholarly')?3:1}else if(id==='listen'){val=5}else if(id==='confess'){val=7;state.private.secret+=3}else if(id==='business'){state.life.authority+=2;val=p.traits.includes('ambitious')?3:-1}else if(id==='approach'){state.life.courage+=3;val=p.traits.includes('martial')?4:1}else if(id==='guard'){state.private.secret-=2;val=p.traits.includes('cautious')?3:0}else{state.stats.intelligence+=1;val=1}livingAddMemory(p.id,j.event.title,choice.label,val,3);j.log.push({step:j.step,title:j.event.title,choice:choice.label});j.step++;if(j.step>=j.total){let id=j.destination,r=state.regions[id],m=COUNTRY_META[id];if(r&&grandOwnsRegion(id)){r.loyalty+=4;r.unrest-=2}else if(m)state.relations[m.key]+=6;grandArrive(id);let text=`Die Reise nach ${j.destinationName} endet nach ${j.total} prägenden Etappen. ${j.companionName} erinnert sich besonders an „${j.log.at(-1).choice}“.`;l.journeyHistory.unshift({...j,endedTurn:state.turn});l.journeyHistory=l.journeyHistory.slice(0,20);l.journey=null;recordDecision(`Königsreise · ${j.destinationName}`,text,{kind:'private'});toast('Die Königsreise endet',j.destinationName)}else j.event=livingJourneyEvent(j);normalizeState();persist();render();return true}

function livingProductionPanel(){let e=ensureDepth().economy,l=ensureLiving(),cards=Object.entries(LIVING_CHAINS).map(([id,c])=>{let x=l.production.chains[id],inputs=Object.entries(c.inputs).map(([g,n])=>`${DEPTH_GOODS[g].label} ${e.goods[g].stock}/${n}`).join(' · '),used=x.usedTurn===state.turn;return `<article class="chain-card ${x.efficiency<40?'shortage':''}"><div class="chain-head"><i>${c.icon}</i><div><small>STUFE ${x.level} · EFFIZIENZ ${Math.round(x.efficiency)}%</small><h3>${c.name}</h3></div><b>${Math.round(x.stock)}<span>VORRAT</span></b></div><p>${c.text}</p><div class="chain-inputs">${inputs}</div><div class="chain-flow"><i><b style="width:${x.efficiency}%"></b></i></div><div class="chain-actions"><button data-chain-action="${id}:invest" ${used||x.level>=5||state.reserve<1800000*x.level?'disabled':''}>${x.level>=5?'MAXIMAL AUSGEBAUT':'KAPAZITÄT AUSBAUEN'}<span>${x.level>=5?'Stufe 5':fmt(1800000*x.level)+' ₲'}</span></button><button data-chain-action="${id}:priority" class="${x.priority?'active':''}" ${used?'disabled':''}>${x.priority?'PRIORITÄT LÖSEN':'KRONPRIORITÄT'}<span>Andere Ketten erhalten weniger Material</span></button></div></article>`}).join('');return panel('PRODUKTIONSKETTEN DES REICHES','Rohstoffe werden zu Brot, Waffen, Schiffen, Verwaltung und Exportgütern',`<div class="production-summary"><span><b>${Math.round(l.production.chains.provisions.stock)}</b> Proviant</span><span><b>${Math.round(l.production.chains.arms.stock)}</b> Waffen</span><span><b>${Math.round(l.production.chains.ships.stock)}</b> Schiffskapazität</span><span><b>${Math.round(l.production.chains.administration.stock)}</b> Verwaltung</span></div><div class="chain-grid">${cards}</div>`,'span-12')}
function livingChainAction(code){let [id,act]=code.split(':'),l=ensureLiving(),x=l.production.chains[id],c=LIVING_CHAINS[id];if(!x||x.usedTurn===state.turn)return false;if(act==='invest'){let cost=1800000*x.level;if(state.reserve<cost||x.level>=5)return false;state.reserve-=cost;x.level++;x.efficiency+=5;x.usedTurn=state.turn;recordDecision(`Produktionskette · ${c.name}`,`Werkstätten, Lager und Ausbildung der Stufe ${x.level} werden finanziert. Mehr Kapazität benötigt künftig auch mehr Rohstoffe.`,{kind:'economy'})}else if(act==='priority'){x.priority=!x.priority;x.usedTurn=state.turn;recordDecision(`Produktionspriorität · ${c.name}`,x.priority?'Fuhrwerke und Verträge liefern dieser Kette zuerst. Andere Produktionszweige können deshalb Material verlieren.':'Die Sonderpriorität endet; Material wird wieder breiter verteilt.',{kind:'economy'})}else return false;normalizeState();persist();render(false);return true}
function livingProductionTick(){let l=ensureLiving(),e=ensureDepth().economy,priorities=Object.values(l.production.chains).filter(x=>x.priority).length;for(const [id,c] of Object.entries(LIVING_CHAINS)){let x=l.production.chains[id],possible=Infinity;for(const [g,n] of Object.entries(c.inputs))possible=Math.min(possible,Math.floor(e.goods[g].stock/n));let target=Math.max(1,Math.round(c.base*x.level*(x.priority?1.35:priorities?.88:1))),made=Math.min(target,possible);for(const [g,n] of Object.entries(c.inputs))e.goods[g].stock=Math.max(0,e.goods[g].stock-made*n);x.stock+=made;x.efficiency=clamp(25+made/target*70,10,100);if(made<target*.4)livingNews(`${c.name}: Produktion stockt`,`Fehlende Vorprodukte begrenzen die Kette. ${Object.entries(c.inputs).filter(([g,n])=>e.goods[g].stock<n).map(([g])=>DEPTH_GOODS[g].label).join(', ')||'Transport und Kapazität'} fehlen.`,'production')}let p=l.production.chains.provisions,a=l.production.chains.arms,s=l.production.chains.ships,adm=l.production.chains.administration,court=l.production.chains.courtgoods,war=Object.values(state.diplo||{}).some(d=>d.war);let foodUse=war?5:2;p.stock=Math.max(0,p.stock-foodUse);if(p.stock<4){state.armies[0].morale-=3;state.factions.people-=2}if(war){a.stock=Math.max(0,a.stock-3);if(a.stock<3)state.stats.army-=1}s.stock=Math.max(0,s.stock-1);if(s.stock>15)state.stats.navy+=.2;adm.stock=Math.max(0,adm.stock-2);if(adm.stock<3)ensureGrand().government.mandate-=1;if(court.stock>18){state.reserve+=220000;court.stock-=2}}

function livingTraditionPanel(){let t=ensureLiving().traditions,can=state.year-t.lastAdoptedYear>=4,groups=Object.entries(LIVING_TRADITIONS).map(([cat,d])=>`<div class="tradition-family"><small>${d.label}</small>${Object.entries(d.options).map(([id,o])=>`<button data-tradition-action="${cat}:${id}" class="${t.adopted[cat]===id?'active':''}" ${t.adopted[cat]===id||!can?'disabled':''}><b>${o[0]}</b><span>${o[1]}</span></button>`).join('')}</div>`).join('');return panel('TRADITIONEN DES HAUSES VALEDOR',`${t.reputation} dynastisches Gewicht · ${can?'Eine neue Tradition kann geprägt werden':'Nächste Prägung ab '+(t.lastAdoptedYear+4)}`,`<div class="tradition-intro"><div class="tradition-seal">V</div><div><h2>Was diese Familie für selbstverständlich hält</h2><p>Traditionen sind keine einmaligen Boni. Sie beeinflussen Erziehung, Nachfolge, Beziehungen und die Erwartungen späterer Generationen.</p></div></div><div class="tradition-grid">${groups}</div>`,'span-12')}
function livingTraditionAction(code){let [cat,id]=code.split(':'),l=ensureLiving(),t=l.traditions,d=LIVING_TRADITIONS[cat],o=d?.options[id];if(!o||t.adopted[cat]===id||state.year-t.lastAdoptedYear<4)return false;let old=t.adopted[cat];t.adopted[cat]=id;t.lastAdoptedYear=state.year;t.reputation+=5;t.history.unshift({year:state.year,cat,id,old});let text=`Das Haus Valedor erklärt „${o[0]}“ zur gelebten Familientradition. ${o[1]} Künftige Familienentscheidungen werden daran gemessen.`;recordDecision(`Dynastietradition · ${o[0]}`,text,{kind:'private'});livingTraditionApply(cat,id);persist();render();return true}
function livingTraditionApply(cat,id){if(cat==='education'){if(id==='books')state.life.education+=5;else if(id==='court')state.life.diplomacy+=4;else state.life.martial+=4}else if(cat==='marriage'){state.private.queen+=3;if(id==='alliance')for(const n in state.relations)state.relations[n]+=2}else if(cat==='coronation')state.stats.legitimacy+=5;else if(cat==='bastards'){if(id==='integrate')state.factions.nobles-=4;else state.stats.legitimacy+=2}else if(cat==='service')state.factions[id==='charity'?'people':'officers']+=4}
function livingTraditionEcho(words,kind){let t=ensureLiving().traditions.adopted;if(t.education==='books'&&/buch|schule|wissen|akadem/.test(words))ensureLiving().traditions.reputation+=.4;if(t.education==='arms'&&kind==='war')ensureLiving().traditions.reputation+=.4;if(t.marriage==='love'&&kind==='private'&&/ehe|liebe|gemah/.test(words))ensureLiving().traditions.reputation+=.5;if(t.service==='charity'&&/hilfe|arm|brot|fürsorge/.test(words))ensureLiving().traditions.reputation+=.4}

function livingEraPanel(){let l=ensureLiving(),idx=LIVING_AGES.findIndex(a=>a.id===l.age.id),era=LIVING_AGES[idx]||LIVING_AGES[0],next=LIVING_AGES[idx+1],progress=next?clamp(Math.round((state.year-era.year)/(next.year-era.year)*100),0,100):100;return panel('DIE ZEIT VERÄNDERT DAS SPIEL',era.name,`<div class="historical-age"><div><small>SEIT ${l.age.entered}</small><h2>${era.name}</h2><p>${era.text}</p><blockquote>${era.effects}</blockquote></div><div class="age-progress"><b>${progress}%</b><span>${next?'NÄCHSTER WANDEL: '+next.name:'VALDORIA PRÄGT SEINE EIGENE ZEIT'}</span><i><em style="width:${progress}%"></em></i></div></div><div class="age-timeline">${LIVING_AGES.map(a=>`<div class="${a.year<=state.year?'reached':''} ${a.id===era.id?'current':''}"><b>${a.year}</b><span>${a.name}</span></div>`).join('')}</div>`,'span-12')}
function livingEraTick(){let l=ensureLiving(),eligible=LIVING_AGES.filter(a=>a.year<=state.year),next=eligible.at(-1);if(!next||next.id===l.age.id)return;let old=LIVING_AGES.find(a=>a.id===l.age.id);l.age.id=next.id;l.age.entered=state.year;l.age.history.unshift({year:state.year,from:old?.id,to:next.id});let text=`Chronisten nennen die neue Zeit „${next.name}“. ${next.text} ${next.effects}`;livingNews(next.name,text,'age');state.events.unshift({turn:state.turn,date:dateLabel(),title:next.name,text});if(next.id==='print')state.stats.intelligence+=3;else if(next.id==='powder')state.stats.army+=3;else if(next.id==='ocean'){state.stats.navy+=3;state.stats.trade+=2}else if(next.id==='confession')for(const p of Object.values(ensureGrand().provinces))p.harmony-=3;else if(next.id==='credit'){state.stats.trade+=4;state.inflation+=.4}}

function livingRelationshipPanel(){let l=ensureLiving(),people=l.people.filter(p=>p.alive).sort((a,b)=>b.influence-a.influence).slice(0,14),cards=people.map(p=>{let traits=p.traits.map(id=>`<span title="${LIVING_TRAITS[id][1]}">${LIVING_TRAITS[id][2]} ${LIVING_TRAITS[id][0]}</span>`).join(''),memory=p.memories[0];return `<article class="living-person ${p.relation<30?'hostile':''}"><div class="person-age"><b>${p.age}</b><small>JAHRE</small></div><div><small>${p.role}</small><h3>${p.name}</h3><div class="person-traits">${traits}</div><p>${memory?`Erinnert sich: „${memory.title}“`:'Noch keine prägende persönliche Erinnerung.'}</p><div class="person-bars"><span>Bindung<i><b style="width:${p.relation}%"></b></i></span><span>Vertrauen<i><b style="width:${p.trust}%"></b></i></span></div></div><button data-person-action="${p.id}:meet" ${p.metTurn===state.turn||state.private.actionPoints<1?'disabled':''}>PERSÖNLICH SPRECHEN</button></article>`}).join('');return panel('MENSCHEN, DIE SICH GEGENSEITIG ERINNERN',`${people.length} gegenwärtige Schlüsselfiguren · Beziehungen bestehen auch ohne den König`,`<div class="relationship-network">${cards}</div>`,'span-12')}
function livingSocialPanel(){let l=ensureLiving(),people=Object.fromEntries(l.people.filter(p=>p.alive).map(p=>[p.id,p])),links=Object.entries(l.relations).filter(([key])=>key.split('::').every(id=>people[id])).sort((a,b)=>Math.max(b[1].affinity,b[1].rivalry)-Math.max(a[1].affinity,a[1].rivalry)).slice(0,10);let rows=links.map(([key,r])=>{let [a,b]=key.split('::'),left=people[a],right=people[b],tone=r.rivalry>55?'RIVALITÄT':r.trust>65?'VERTRAUENSBUND':r.affinity>60?'ZUNEIGUNG':'ARBEITSBEZIEHUNG',value=Math.round(r.rivalry>55?r.rivalry:r.affinity);return `<article class="social-link ${r.rivalry>55?'rival':''}"><div><small>${left.role}</small><b>${left.name}</b></div><i><em style="width:${value}%"></em><span>${tone} · ${value}</span></i><div><small>${right.role}</small><b>${right.name}</b></div></article>`}).join('')||'<div class="empty">Die ersten Gespräche und gemeinsamen Entscheidungen werden das Beziehungsnetz des Hofes sichtbar machen.</div>';return panel('BEZIEHUNGEN UNTEREINANDER','Bündnisse, Freundschaften und Rivalitäten verändern sich auch ohne königlichen Klick',`<div class="social-network">${rows}</div>`,'span-12')}
function livingPersonAction(code){let [id,act]=code.split(':'),p=livingPerson(id);if(!p||act!=='meet'||p.metTurn===state.turn||state.private.actionPoints<1)return false;state.private.actionPoints--;p.metTurn=state.turn;let topic=p.memories[0],val=topic&&topic.valence<0?4:3;livingAddMemory(id,'Persönliches Gespräch',topic?`Der König sprach über „${topic.title}“, statt die Erinnerung zu übergehen.`:'Der König nahm sich ohne unmittelbare Forderung Zeit.',val,3);let others=ensureLiving().people.filter(x=>x.alive&&x.id!==id),other=others[livingHash(id+state.turn)%others.length],r=livingRelation(id,other.id);r.affinity+=p.traits.includes('charismatic')?2:1;r.trust+=1;recordDecision(`Gespräch mit ${p.name}`,`Das Gespräch verändert nicht nur die Bindung an den König. ${p.name} sucht anschließend ${other.name} auf; zwischen beiden wächst neues Vertrauen.`,{kind:'private'});normalizeState();persist();render();return true}

function livingTreatiesOverview(){let l=ensureLiving(),active=l.treaties.filter(t=>t.status==='active'),rows=active.map(t=>`<article><div><small>MIT ${t.country} · BIS ${t.expiresYear}</small><h3>${t.peace?'FRIEDENSVERTRAG':'STAATSVERTRAG'}</h3><p>${t.clauses.map(c=>LIVING_TREATY_CLAUSES[c].name).join(' · ')}</p></div><b>${Math.round(t.trust)}<span>VERTRAUEN</span></b></article>`).join('')||'<div class="empty">Noch bindet kein mehrjähriger Klauselvertrag Valdoria an einen fremden Hof.</div>';return panel('VERTRÄGE, DIE DIE WELT BINDEN',`${active.length} aktive Verträge`,`<div class="treaty-overview">${rows}</div>`,'span-12')}
function livingGenerationPanel(){let l=ensureLiving(),foreign=Object.keys(state.relations).map(n=>[n,livingForeignRealm(n)]);return panel('DIE HERRSCHERHÄUSER DER WELT','Jeder Hof altert, stirbt und erinnert anders',`<div class="foreign-generations">${foreign.map(([n,f])=>`<article><small>${n} · GENERATION ${f.generation}</small><h3>${f.ruler}</h3><p>${f.age} Jahre · ${f.temper} · Gesundheit ${Math.round(f.health)}</p><div><span>NACHFOLGE</span><b>${f.heir}, ${f.heirAge}</b></div></article>`).join('')}</div>`,'span-12')}
function livingChroniclePanel(){let l=ensureLiving(),dead=l.people.filter(p=>!p.alive).slice(-8),memories=l.people.reduce((s,p)=>s+p.memories.length,0);return panel('DIE LEBENDIGE DYNASTIE',`${l.civilHistory.length} Thronkrisen · ${l.treaties.length} Verträge · ${memories} Erinnerungen`,`<div class="living-chronicle"><div><small>GEGENWÄRTIGES ZEITALTER</small><b>${LIVING_AGES.find(a=>a.id===l.age.id)?.name}</b><span>Seit ${l.age.entered}</span></div><div><small>HAUSTRADITIONEN</small><b>${Object.keys(l.traditions.adopted).length} geprägt</b><span>Dynastisches Gewicht ${Math.round(l.traditions.reputation)}</span></div><div><small>VERSTORBENE SCHLÜSSELFIGUREN</small><b>${dead.length}</b><span>${dead.map(p=>p.name).join(', ')||'Noch niemand in dieser Chronik'}</span></div><div><small>KÖNIGSREISEN</small><b>${l.journeyHistory.length}</b><span>Jede Reise hinterließ gemeinsame Erinnerungen</span></div></div>`,'span-12')}
function livingRealmPulse(){let l=ensureLiving(),c=l.civilWar,era=LIVING_AGES.find(a=>a.id===l.age.id),prod=Object.values(l.production.chains).filter(x=>x.efficiency<40).length;return `<section class="living-realm-pulse"><div><small>ZEITALTER</small><b>${era.name}</b><span>Seit ${l.age.entered}</span></div><div><small>INNERER FRIEDEN</small><b>${c?'BÜRGERKRIEG: '+Math.round(c.progress)+'%':'Risiko '+livingCivilRisk()+'%'}</b><span>${c?c.phase:'Ansprüche und Erinnerungen wirken weiter'}</span></div><div><small>PRODUKTION</small><b>${prod?prod+' stockende Ketten':'Lieferketten tragen das Reich'}</b><span>Rohstoffe werden tatsächlich verarbeitet</span></div></section>`}

function livingNormalize(s){let l=s.living;if(!l)return;for(const p of l.people){p.age=Math.max(0,Math.round(p.age));p.health=clamp(Math.round(p.health),0,100);p.relation=clamp(Math.round(p.relation),0,100);p.trust=clamp(Math.round(p.trust),0,100);p.influence=clamp(Math.round(p.influence),0,100)}for(const r of Object.values(l.relations)){r.affinity=clamp(Math.round(r.affinity),0,100);r.trust=clamp(Math.round(r.trust),0,100);r.attraction=clamp(Math.round(r.attraction),0,100);r.rivalry=clamp(Math.round(r.rivalry),0,100)}for(const x of Object.values(l.production.chains)){x.level=clamp(Math.round(x.level),1,5);x.stock=Math.max(0,Math.round(x.stock));x.efficiency=clamp(Math.round(x.efficiency),0,100)}if(l.civilWar){l.civilWar.progress=clamp(l.civilWar.progress,0,100);l.civilWar.support=clamp(l.civilWar.support,0,100);l.civilWar.royal=clamp(l.civilWar.royal,0,100)}}
function livingSocialTick(){let l=ensureLiving(),people=l.people.filter(p=>p.alive);if(people.length<2)return;for(let i=0;i<3;i++){let a=people[livingHash(`${state.nameSeed}:social:a:${state.turn}:${i}`)%people.length],b=people[livingHash(`${state.nameSeed}:social:b:${state.turn}:${i}`)%people.length];if(a.id===b.id)b=people[(people.indexOf(a)+1+i)%people.length];let r=livingRelation(a.id,b.id),shared=a.group===b.group?1.2:0,compatible=a.traits.some(t=>b.traits.includes(t))?1.1:0,friction=(a.traits.includes('ambitious')&&b.traits.includes('ambitious')?1.6:0)+(a.traits.includes('bitter')||b.traits.includes('bitter')?.5:0);r.affinity+=shared+compatible-friction*.35;r.trust+=shared*.5-friction*.3;r.rivalry+=friction-compatible*.25;r.memories.unshift({turn:state.turn,year:state.year,text:friction>compatible?'Ein Streit um Einfluss verschärfte den Gegensatz.':'Gemeinsame Arbeit schuf Vertrautheit.'});r.memories=r.memories.slice(0,8);if(r.rivalry>70&&state.turn%5===0)livingNews(`Rivalität am Hof: ${a.name} und ${b.name}`,`Eine länger gewachsene Feindschaft zwischen ${a.role} und ${b.role} beeinflusst Informationen, Ämter und Bündnisse am Hof.`,'person')}}
function livingTurn(){livingTreatyTick();livingProductionTick();livingCivilTick();livingSocialTick();let l=ensureLiving();for(const p of l.people.filter(p=>p.alive)){p.relation+=(p.traits.includes('loyal')?.15:0)-(p.traits.includes('bitter')?.1:0);for(const m of p.memories)m.importance=Math.max(1,m.importance-(state.year-m.year>8?.08:0))}livingEraTick()}
function livingAnnualTick(){let l=ensureLiving();if(l.annualYear===state.year)return;l.annualYear=state.year;livingGenerationTick();livingEraTick();for(const r of Object.values(l.relations)){r.affinity+=(50-r.affinity)*.04;r.rivalry=Math.max(0,r.rivalry-.5)}for(const p of l.people.filter(p=>p.alive))livingEvolvePerson(p)}
function livingSuccessionReset(){let l=ensureLiving();for(const p of l.people.filter(p=>p.alive)){let inherited=p.memories.slice(0,4).map(m=>({...m,title:`Unter der alten Krone: ${m.title}`,importance:Math.max(1,m.importance-1)}));p.memories=inherited;p.relation=clamp(35+p.relation*.35,20,75);p.trust=clamp(30+p.trust*.3,15,70)}l.capital.location='throne';l.capital.usedTurn=0;l.journey=null;l.traditions.reputation+=3;livingNews('Eine neue Person trägt die alten Erwartungen','Menschen, Verträge und Traditionen überleben den Monarchen. Der neue König erbt ihre Geschichten, aber keine fertige persönliche Beziehung.','generation')}
function livingBindUI(){document.querySelectorAll('[data-living-treaty]').forEach(b=>b.onclick=()=>livingTreatyAction(b.dataset.livingTreaty));document.querySelectorAll('[data-civil-action]').forEach(b=>b.onclick=()=>livingCivilAction(b.dataset.civilAction));document.querySelectorAll('[data-capital-action]').forEach(b=>b.onclick=()=>livingCapitalAction(b.dataset.capitalAction));document.querySelectorAll('[data-journey-setup]').forEach(b=>b.onclick=()=>livingJourneySetup(b.dataset.journeySetup));document.querySelectorAll('[data-journey-action]').forEach(b=>b.onclick=()=>livingJourneyAction(b.dataset.journeyAction));document.querySelectorAll('[data-chain-action]').forEach(b=>b.onclick=()=>livingChainAction(b.dataset.chainAction));document.querySelectorAll('[data-tradition-action]').forEach(b=>b.onclick=()=>livingTraditionAction(b.dataset.traditionAction));document.querySelectorAll('[data-person-action]').forEach(b=>b.onclick=()=>livingPersonAction(b.dataset.personAction))}
